import Ajv from 'ajv';
import type { ErrorObject, RequiredParams, TypeParams, ValidateFunction } from 'ajv';
import type { ToolDefinition } from '../../types/ai.js';
import type { OutgoingMessage } from '../../types/messages.js';
import { log } from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validateInput?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    if (typeof definition === 'function') {
      const resolved = definition();
      compileCachedSchema(resolved.name, resolved.inputSchema);
      this.tools.set(resolved.name, {definitionSource: definition, execute});
      return;
    }
    const validateInput = compileSchema(definition.name, definition.inputSchema);
    this.tools.set(definition.name, {definitionSource: definition, execute, validateInput});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema and returns a rejection ToolResponse on failure; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.resolveValidator(tool);
    if (!validate(input)) {
      return rejectInvalidInput(name, validate.errors!);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveValidator(tool: StoredTool): ValidateFunction {
    if (tool.validateInput) return tool.validateInput;
    const resolved = this.resolveDefinition(tool.definitionSource);
    return compileCachedSchema(resolved.name, resolved.inputSchema);
  }
}

const compiledSchemas = new WeakMap<Record<string, unknown>, ValidateFunction>();

function compileCachedSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  const cached = compiledSchemas.get(schema);
  if (cached) return cached;
  const compiled = compileSchema(toolName, schema);
  compiledSchemas.set(schema, compiled);
  return compiled;
}

const ajv = new Ajv({allErrors: true, format: false});

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

interface ValidationFailure {
  path: string;
  constraint: string;
  summary: string;
}

function rejectInvalidInput(toolName: string, errors: ErrorObject[]): ToolResponse {
  const failures = errors.map(describeError);
  log.warn('tool', 'input validation failed', {
    name: toolName,
    failures: failures.map(({path, constraint}) => ({path, constraint})),
  });
  const reasons = failures.map(failure => failure.summary).join('; ');
  return {result: `Invalid input for tool "${toolName}": ${reasons}`};
}

const ERROR_FORMATTERS: Record<string, (basePath: string, error: ErrorObject) => ValidationFailure> = {
  required: formatRequiredError,
  type: formatTypeError,
};

function describeError(error: ErrorObject): ValidationFailure {
  const basePath = normalizeDataPath(error.dataPath);
  const formatter = ERROR_FORMATTERS[error.keyword] ?? formatConstraintError;
  return formatter(basePath, error);
}

function normalizeDataPath(dataPath: string): string {
  return dataPath.replace(/^\./, '');
}

function formatRequiredError(basePath: string, error: ErrorObject): ValidationFailure {
  const {missingProperty} = error.params as RequiredParams;
  const path = [basePath, missingProperty].filter(Boolean).join('.');
  return {
    path,
    constraint: 'required',
    summary: `missing required property "${path}"`,
  };
}

function formatTypeError(basePath: string, error: ErrorObject): ValidationFailure {
  const {type: expectedType} = error.params as TypeParams;
  return {
    path: basePath,
    constraint: `type:${expectedType}`,
    summary: `property "${basePath}" must be of type ${expectedType}`,
  };
}

function formatConstraintError(basePath: string, error: ErrorObject): ValidationFailure {
  return {
    path: basePath,
    constraint: error.keyword,
    summary: `property "${basePath}" failed ${error.keyword} constraint`,
  };
}

import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('rejects input missing a required field with a ToolResponse and zero executor calls', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather_by_location',
        description: 'Look up weather by location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('weather_by_location', {});

    expect({
      executorCalls,
      namesLocationAsRequired: /required.*"location"/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      namesLocationAsRequired: true,
    });
  });

  it('passes valid input including unlisted extra properties through to the executor unchanged once', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'forecast_tool',
        description: 'Fetch forecast',
        promptInstructions: 'Use for forecasts',
        examplePrompts: ['Forecast for Berlin'],
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string', default: 'London'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return {
          result: 'ok',
          clientMessages: [{type: 'entry_commit', index: 0}],
          suppressAssistantResponse: true,
        };
      }
    );

    const payload = {location: 'Berlin', units: 'celsius', extraKey: 42};
    const response = await registry.execute('forecast_tool', payload);

    expect({
      receivedInputs,
      result: response.result,
      hasTool: registry.has('forecast_tool'),
      definedName: registry.get('forecast_tool')?.definition.name,
      absentTool: registry.get('unknown_tool'),
      instructions: registry.getPromptInstructions(),
      examples: registry.getExamplePrompts(),
    }).toEqual({
      receivedInputs: [{location: 'Berlin', units: 'celsius', extraKey: 42}],
      result: 'ok',
      hasTool: true,
      definedName: 'forecast_tool',
      absentTool: undefined,
      instructions: ['forecast_tool: Use for forecasts'],
      examples: ['Forecast for Berlin'],
    });
  });

  it('rejects wrong-typed and non-enum fields naming the field path and constraint without leaking values', async () => {
    const emittedLogs: string[] = [];
    const recordLog = (category: string, message: string, fields?: Record<string, unknown>) => {
      emittedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {debug: recordLog, info: recordLog, warn: recordLog, error: recordLog};
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'patient_lookup',
        description: 'Look up patient record',
        inputSchema: {
          type: 'object',
          properties: {
            patientId: {type: 'string'},
            department: {type: 'string', enum: ['cardiology', 'neurology']},
          },
          required: ['patientId'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'record';
      }
    );

    const response = await registry.execute('patient_lookup', {
      patientId: 987654321,
      department: 'secret-ward',
    });

    expect({
      executorCalls,
      namesFieldAndType: /"patientId".*string/.test(response.result),
      namesEnumField: /"department".*enum/.test(response.result),
      leakedInResult: /987654321|secret-ward/.test(response.result),
      leakedInLogs: emittedLogs.some(line => /987654321|secret-ward/.test(line)),
    }).toEqual({
      executorCalls: 0,
      namesFieldAndType: true,
      namesEnumField: true,
      leakedInResult: false,
      leakedInLogs: false,
    });
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const rawSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition: ToolDefinition = {
      name: 'cached_static_tool',
      description: 'Counts schema accesses',
      get inputSchema() {
        schemaReads += 1;
        return rawSchema;
      },
    };
    registry.register(definition, async input => String(input.location));

    const results: string[] = [];
    for (let i = 0; i < 10; i++) {
      const response = await registry.execute('cached_static_tool', {location: `city-${i}`});
      results.push(response.result);
    }

    expect({schemaReads, callCount: results.length}).toEqual({schemaReads: 1, callCount: 10});
  });

  it('validates each call against the current schema returned by a function-valued definition source', async () => {
    const registry = new ToolRegistry();
    const firstSchema = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const secondSchema = {
      type: 'object',
      properties: {country: {type: 'string'}},
      required: ['country'],
    };
    let activeSchema: Record<string, unknown> = firstSchema;
    registry.register(
      () => ({
        name: 'dynamic_geo_tool',
        description: 'Switches schema between calls',
        inputSchema: activeSchema,
      }),
      async input => JSON.stringify(input)
    );

    const firstPass = await registry.execute('dynamic_geo_tool', {city: 'Paris'});
    activeSchema = secondSchema;
    const staleRejected = await registry.execute('dynamic_geo_tool', {city: 'Paris'});
    const updatedPass = await registry.execute('dynamic_geo_tool', {country: 'France'});

    expect({
      firstPass: firstPass.result,
      staleRejectedMentionsCountry: /required.*"country"/i.test(staleRejected.result),
      updatedPass: updatedPass.result,
    }).toEqual({
      firstPass: '{"city":"Paris"}',
      staleRejectedMentionsCountry: true,
      updatedPass: '{"country":"France"}',
    });
  });

  it('throws Unknown tool for an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
  });
});

